#include "rinkfit/joint_explicit.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("old new out");auto old=rinkfit::JointEventModel::load(argv[1]),now=rinkfit::JointEventModel::load(argv[2]);const int mi=129,pi=0;double difference=0;int checked=0;for(const auto&v:now.station_intervals(mi,pi))for(int k=0;k<=96;++k){const double s=v[0]+(v[1]-v[0])*k/96.;auto a=old.layout(0,mi,pi,old.shots[0].first_pts),b=now.layout(0,mi,pi,now.shots[0].first_pts);auto evaluate=[&](auto&m,auto&l){auto p=m.pointers(l);auto g=m.global(l,p.data());std::vector<const double*>lp;std::vector<double>geometry;auto e=m.legacy_layout(l,lp,g,p.data(),geometry);return m.world_point(l,s,lp.data(),e,m.shots[0].math);};auto x=evaluate(old,a),y=evaluate(now,b);for(int j=0;j<3;++j)difference=std::max(difference,std::abs(x[j]-y[j]));if(!now.station_allowed(mi,pi,s))throw std::runtime_error("lost legal endpoint");++checked;}
 double maxad=0;for(double s:{.2,31.25/75.,.5,49.25/75.,.8}){using J=ceres::Jet<double,1>;J x(s);x.v[0]=1.;auto q=now.station_domain(mi,pi,x);double h=1e-8,fd=(now.station_domain(mi,pi,s+h)-now.station_domain(mi,pi,s-h))/(2*h);maxad=std::max(maxad,std::abs(fd-q.v[0]));}
 auto l=now.layout(0,mi,pi,now.shots[0].first_pts);bool rejected=true;for(double s:{31.5/75.,49.5/75.}){rejected&=!now.project_rs(l,s).valid;auto legacy=now.legacy_snapshot(0);rejected&=!now.certified_projection(legacy,l,s).valid;}
 rinkfit::eventio::Json result={{"schema","rinkfit.actual_native_finite_station_domain_QA.v1"},{"actual_legal_world_points",checked},{"world_max_difference",difference},{"banned_edges_rejected_by_both_native_RS_entrypoints",rejected},{"max_station_domain_AD_FD_difference",maxad},{"passed",difference==0&&rejected&&maxad<1e-7}};std::ofstream f(argv[3]);f<<result.dump(2);std::cout<<result.dump(2);return result["passed"].get<bool>()?0:2;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
